      "id": "DMSR-5913",
      "title": "DMS Initialization Component",
      "text": "The DMS shall contain a component that, at each Center, can initialize the DM Subsystem into a well-deﬁned safe state when powered up."
    },
    {
      "id": "DMSR-3500",
      "title": "Data Product Ingest",
      "text": "The DMS shall provide software to ingest data products into the Science Data Archive."
    },
    {
      "id": "DMSR-2318",
      "title": "Data Product and Raw Data Access",
      "text": "The DMS shall provide software for Data Access Services to list and retrieve image, ﬁle, and catalog data products (including raw telescope images and calibration data), their associated metadata, their provenance, or any combination thereof, independent of their actual storage location."
    },
    {
      "id": "DMSR-3342",
      "title": "Bulk Download Service",
      "text": "The DMS shall provide software to enable bulk download of data products and raw data, subject to network bandwidth."
    },
    {
      "id": "DMSR-7026",
      "title": "Provide Image Access Services",
      "text": "The DMS shall provide a service for Image Access through community data access protocols, to support programmatic search and retrieval of images or image cut-outs. The service shall support one or more community standard formats, including the LSST pipeline input format."
    },
    {
      "id": "DMSR-1680",
      "title": "Control of Level-1 Production",
      "text": "The DMS shall contain a component to control all Level-1 Data Product production."
    },
    {
      "id": "DMSR-5060",
      "title": "Production Orchestration",
      "text": "The DMS shall provide software to orchestrate execution of productions, including deploying pipelines on a computing platform."
    },
    {
      "id": "DMSR-4277",
      "title": "Production Monitoring",
      "text": "The DMS shall provide software to monitor execution of pipelines in real time."
    },
    {
      "id": "DMSR-1395",
      "title": "Production Fault Tolerance",
      "text": "The DMS shall provide software to detect faults in pipeline execution and recover when possible."
    }
